const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Norwegian Sea region
  const norseaSea = ee.Geometry.Rectangle([0, 60, 20, 75]);

  // Target date: June 5, 2019 ± 5 days
  const startDate = '2019-06-01';
  const endDate = '2019-06-10';

  // Sentinel-2 collection with cloud filtering
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(norseaSea)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  const colSize = col.size().getInfo();
  if (colSize === 0) {
    console.log('No Sentinel-2 images found. Trying Landsat 8...');
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(norseaSea)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 50));
    const colSizeLandsat = col.size().getInfo();
    if (colSizeLandsat === 0) {
      console.log('No data found for Norwegian Sea, June 5 2019');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  console.log(`Images found: ${colSize > 0 ? colSize : col.size().getInfo()}`);

  // Use median composite to reduce noise
  const composite = col.median();

  // Calculate NDCI (Normalized Difference Chlorophyll Index)
  // NDCI = (B5 - B4) / (B5 + B4) for Sentinel-2
  const ndci = composite.normalizedDifference(['B5', 'B4']).rename('NDCI');

  // Also check pixel validity
  const validPixels = ndci.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: norseaSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  if (validPixels === 0) {
    console.log('No valid pixels after cloud masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // Calculate mean NDCI
  const meanNDCI = ndci.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: norseaSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  // Calculate max NDCI (phytoplankton bloom indicator)
  const maxNDCI = ndci.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: norseaSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDCI').getInfo();

  if (meanNDCI === null || isNaN(meanNDCI)) {
    console.log('NDCI calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Composite images: ${colSize > 0 ? colSize : col.size().getInfo()}`);
  console.log(`Valid pixels: ${validPixels}`);
  console.log(`Mean NDCI: ${meanNDCI.toFixed(4)}`);
  console.log(`Max NDCI: ${maxNDCI.toFixed(4)}`);

  // Phytoplankton blooms typically show NDCI > 0.1 (elevated chlorophyll)
  // Strong blooms: NDCI > 0.15
  const bloomThreshold = 0.10;

  if (maxNDCI > bloomThreshold) {
    console.log(`Bloom signature detected (max NDCI ${maxNDCI.toFixed(4)} > ${bloomThreshold})`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No significant phytoplankton bloom detected (max NDCI ${maxNDCI.toFixed(4)} ≤ ${bloomThreshold})`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
